// Simulate horror content from RSS feed
const testContent = {
  title: "TEST: New Horror Movie Trailer Released",
  link: "https://example.com/horror-trailer",
  description: "A terrifying new horror movie trailer has been released, featuring spine-chilling scenes and jump scares that will leave you on the edge of your seat.",
  pubDate: new Date().toISOString(),
  categories: ['horror', 'movies', 'trailer'],
  test: true
};

return [{ json: testContent }];

// Process test horror content
const crypto = require('crypto');
const item = $input.first().json;

const contentHash = crypto
  .createHash('md5')
  .update(item.title + item.link)
  .digest('hex');

const horrorContent = {
  idempotencyKey: `test-${contentHash}`,
  title: item.title,
  link: item.link,
  description: item.description,
  pubDate: item.pubDate,
  categories: item.categories,
  horrorTags: ['horror', 'test', 'trailer'],
  engagementScore: 85,
  contentHash: contentHash,
  test: true
};

return [{ json: horrorContent }];

// Format test results
const httpResult = $input.first().json;
const originalContent = $input.first().json;

const results = {
  testStatus: 'SUCCESS',
  timestamp: new Date().toISOString(),
  httpStatusCode: httpResult.statusCode || 'N/A',
  contentTitle: originalContent.title,
  idempotencyKey: originalContent.idempotencyKey,
  engagementScore: originalContent.engagementScore,
  notes: 'All test components executed successfully'
};

console.log('✅ Test Results:', JSON.stringify(results, null, 2));

return [{ json: results }];

